//! Zsh completion functions for the commands goatty provides, in
//! `share/zsh/site-functions/` (on the managed shell's `fpath`, after the
//! system's directories):
//!
//! * goatty's own: `goatty` and `goattyd` keep their `_goatty` / `_goattyd`
//!   current whenever they start ([`write`], generated by clap);
//! * goatty's copies of plugin packages' tools (`[[package]] completions`,
//!   like `starship completions zsh`), written by [`for_package`] after the
//!   install, removed with the package ([`backfill`] catches up on copies
//!   installed before). Copies on the system come with their own
//!   completions.
//!
//! Adding or removing a function deletes the completion dump, so the next
//! shell's `compinit` finds it (zsh loads the functions themselves lazily,
//! but the dump records which commands have one).

use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use anyhow::{Context, Result, bail};

use crate::dirs::Dirs;

/// How long a tool may take to print its completions.
const TIMEOUT: Duration = Duration::from_secs(10);

/// The file holding command `name`'s completion function.
pub fn file(dirs: &Dirs, name: &str) -> PathBuf {
    dirs.site_functions_dir().join(format!("_{name}"))
}

/// Make `_name` hold `script` (atomically). Returns whether anything
/// changed; the completion dump is dropped when it did.
pub fn write(dirs: &Dirs, name: &str, script: &str) -> Result<bool> {
    check(name, script)?;
    let path = file(dirs, name);
    if std::fs::read(&path).is_ok_and(|old| old == script.as_bytes()) {
        return Ok(false);
    }
    let dir = dirs.site_functions_dir();
    std::fs::create_dir_all(&dir).with_context(|| format!("create {}", dir.display()))?;
    let tmp = dir.join(format!("._{name}.tmp-{}", std::process::id()));
    std::fs::write(&tmp, script).with_context(|| format!("write {}", tmp.display()))?;
    std::fs::rename(&tmp, &path).with_context(|| format!("write {}", path.display()))?;
    invalidate_dump(dirs);
    Ok(true)
}

/// Remove `_name`. Returns whether it was there.
pub fn remove(dirs: &Dirs, name: &str) -> Result<bool> {
    let path = file(dirs, name);
    match std::fs::remove_file(&path) {
        Ok(()) => {
            invalidate_dump(dirs);
            Ok(true)
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e).with_context(|| format!("remove {}", path.display())),
    }
}

/// [`write`] for goatty's own binaries at startup: failures only log (a
/// read-only data directory mustn't keep goatty from starting).
pub fn write_own(dirs: Option<&Dirs>, name: &str, script: &str) {
    let Some(dirs) = dirs else { return };
    match write(dirs, name, script) {
        Ok(true) => log::info!("updated the zsh completions of {name} in {}", dirs.site_functions_dir().display()),
        Ok(false) => {}
        Err(e) => log::warn!("couldn't write the zsh completions of {name}: {e:#}"),
    }
}

/// Run `exe` with `args` (a package's `completions` command, `exe` being
/// goatty's copy of the program) and keep what it prints as `_<name>`.
pub fn for_package(dirs: &Dirs, name: &str, exe: &Path, args: &[String]) -> Result<bool> {
    let script = generate(exe, args).with_context(|| format!("{} {}", exe.display(), args.join(" ")))?;
    write(dirs, name, &script)
}

/// Generate the functions goatty's copies of packages should have and
/// don't (installed before goatty generated them, or the tool failed
/// then). goattyd runs this when it starts; failures only log.
pub fn backfill(dirs: &Dirs) {
    let mut packages: Vec<goatty_plugin::manifest::Package> =
        crate::builtins::BUILTINS.iter().flat_map(|b| b.manifest().packages.iter().cloned()).collect();
    if let Ok(lock) = crate::plugins::lock::Lock::load(dirs) {
        for (id, entry) in &lock.plugins {
            if let Ok(m) = crate::plugins::lock::manifest_of(dirs, id, entry) {
                packages.extend(m.packages);
            }
        }
    }
    for p in &packages {
        let Some((name, args)) = p.completions.split_first() else { continue };
        if crate::install::link_owner(dirs, name).as_deref() != Some(p.id.as_str()) || file(dirs, name).exists() {
            continue;
        }
        match for_package(dirs, name, &dirs.bin_dir().join(name), args) {
            Ok(_) => log::info!("added the zsh completions of goatty's {name}"),
            Err(e) => log::warn!("no zsh completions for {name}: {e:#}"),
        }
    }
}

/// What `exe args…` prints on stdout, within [`TIMEOUT`].
fn generate(exe: &Path, args: &[String]) -> Result<String> {
    let mut child =
        Command::new(exe).args(args).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().context("start it")?;
    let mut stdout = child.stdout.take().context("no stdout")?;
    let reader = std::thread::spawn(move || {
        let mut buf = Vec::new();
        stdout.read_to_end(&mut buf).map(|_| buf)
    });
    let deadline = Instant::now() + TIMEOUT;
    let status = loop {
        if let Some(s) = child.try_wait()? {
            break s;
        }
        if Instant::now() > deadline {
            let _ = child.kill();
            let _ = child.wait();
            bail!("took longer than {}s", TIMEOUT.as_secs());
        }
        std::thread::sleep(Duration::from_millis(20));
    };
    let out = reader.join().map_err(|_| anyhow::anyhow!("reading its output failed"))??;
    if !status.success() {
        bail!("failed ({status})");
    }
    String::from_utf8(out).context("printed something that isn't text")
}

/// A zsh completion function starts with `#compdef`; `compinit` ignores
/// anything else.
fn check(name: &str, script: &str) -> Result<()> {
    if name.is_empty() || name.contains('/') || name.starts_with('.') {
        bail!("{name:?} is not a command name");
    }
    if !script.starts_with("#compdef") {
        bail!("not a zsh completion function (no #compdef line)");
    }
    Ok(())
}

/// Delete the completion dumps (`zcompdump-<zsh version>` and its compiled
/// `.zwc`), so the next `compinit` scans `fpath` again.
fn invalidate_dump(dirs: &Dirs) {
    let Ok(entries) = std::fs::read_dir(&dirs.cache) else { return };
    for e in entries.flatten() {
        if e.file_name().to_string_lossy().starts_with("zcompdump") {
            let _ = std::fs::remove_file(e.path());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_only_changes_and_drops_the_dump() {
        let tmp = tempfile::tempdir().unwrap();
        let dirs = Dirs::under(tmp.path());
        std::fs::create_dir_all(&dirs.cache).unwrap();
        let dump = dirs.cache.join("zcompdump-5.9");
        std::fs::write(&dump, "").unwrap();

        assert!(write(&dirs, "goattyd", "#compdef goattyd\n_goattyd() {}\n").unwrap());
        assert!(!dump.exists(), "a new function rebuilds the dump");
        assert_eq!(std::fs::read_to_string(file(&dirs, "goattyd")).unwrap(), "#compdef goattyd\n_goattyd() {}\n");

        std::fs::write(&dump, "").unwrap();
        assert!(!write(&dirs, "goattyd", "#compdef goattyd\n_goattyd() {}\n").unwrap());
        assert!(dump.exists(), "nothing changed: the dump stays");

        assert!(write(&dirs, "x", "echo hi").is_err(), "not a completion function");
        assert!(write(&dirs, "../x", "#compdef x").is_err());

        assert!(remove(&dirs, "goattyd").unwrap());
        assert!(!dump.exists());
        assert!(!remove(&dirs, "goattyd").unwrap());
    }

    #[test]
    fn generates_from_a_command() {
        let tmp = tempfile::tempdir().unwrap();
        let dirs = Dirs::under(tmp.path());
        let sh = Path::new("/bin/sh");
        let args = |s: &str| vec!["-c".to_string(), s.to_string()];
        assert!(for_package(&dirs, "demo", sh, &args("printf '#compdef demo\\n_arguments -v\\n'")).unwrap());
        assert!(std::fs::read_to_string(file(&dirs, "demo")).unwrap().starts_with("#compdef demo\n"));
        assert!(for_package(&dirs, "bad", sh, &args("echo nope")).is_err());
        assert!(for_package(&dirs, "bad", sh, &args("exit 3")).unwrap_err().to_string().contains("sh -c exit 3"));
        assert!(!file(&dirs, "bad").exists());
    }
}
